package org.spirchat.engine

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

/** Checks the engine against vectors generated by the TypeScript protocol library. */
class VectorsTest {
    private val vectors: Json.Obj by lazy {
        val repo = System.getProperty("spirchat.repo") ?: "../.."
        Json.parse(File(repo, "packages/protocol/test/vectors.json").readText()) as Json.Obj
    }
    private val now get() = vectors.long("now")!!

    @Test
    fun canonicalJsonMatchesJavaScript() {
        for (case in (vectors["canonical"] as Json.Arr).items) {
            case as Json.Obj
            assertEquals(case.str("json"), case["value"]!!.canonical())
        }
    }

    @Test
    fun validEnvelopesAreAccepted() {
        for ((name, env) in vectors.obj("valid")!!.fields) {
            assertNull(Protocol.validate(env, now), "$name should be valid")
            // Re-parsing the canonical form must also round-trip.
            assertNull(Protocol.validate(Json.parse(env.canonical()), now), "$name canonical round-trip")
        }
    }

    @Test
    fun invalidEnvelopesAreRejected() {
        for ((name, env) in vectors.obj("invalid")!!.fields) {
            assertNotNull(Protocol.validate(env, now), "$name should be invalid")
        }
    }

    @Test
    fun mailboxTagsMatch() {
        for ((_, ident) in vectors.obj("identities")!!.fields) {
            ident as Json.Obj
            assertEquals(ident.str("tag"), Protocol.mailboxTag(ident.str("id")!!))
        }
        val dm = vectors.obj("valid")!!.obj("dm")!!
        assertEquals(vectors.obj("identities")!!.obj("bob")!!.str("tag"), dm.str("to"))
    }

    @Test
    fun numbersFormatLikeJavaScript() {
        val cases = mapOf(
            0.0 to "0", 1.0 to "1", -1.0 to "-1", 1.5 to "1.5", 0.001 to "0.001", 1e-7 to "1e-7",
            1e21 to "1e+21", 123456789012.0 to "123456789012", 33.312 to "33.312", 1.0E-6 to "0.000001",
            1.23e-10 to "1.23e-10", 2.5e22 to "2.5e+22", 1790856000000.0 to "1790856000000",
        )
        for ((d, s) in cases) assertEquals(s, Json.jsNumber(d), "for $d")
    }
}
